+pub(crate) fn span_box_stats(count: usize, mut at: impl FnMut(usize) -> [f64; 4]) -> Option<(P3, f64, f64, bool)> {
+    if count == 0 {
+        return None;
+    }
+    let (mut lo, mut hi) = ([f64::INFINITY; 3], [f64::NEG_INFINITY; 3]);
+    let (mut w_min, mut w_max) = (f64::INFINITY, 0.0_f64);
+    for idx in 0..count {
+        let (p, w) = cart(at(idx))?;
+        w_min = w_min.min(w);
+        w_max = w_max.max(w);
+        for d in 0..3 {
+            lo[d] = lo[d].min(p[d]);
+            hi[d] = hi[d].max(p[d]);
+        }
