+
+pub(crate) fn collect_indices(spans: &[usize], p: usize) -> Vec<usize> {
+    let mut idx: Vec<usize> = spans.iter().flat_map(|&sp| sp - p..=sp).collect();
+    idx.sort_unstable();
+    idx.dedup();
+    idx
