+fn mat3_op_bound(m: &[[f64; 4]; 3]) -> f64 {
+    let mut g = [[0.0_f64; 3]; 3];
+    for r in 0..3 {
+        for c in 0..3 {
+            g[r][c] = (0..3).map(|k| m[k][r] * m[k][c]).sum();
+        }
+    }
+    g.iter().map(|row| row.iter().map(|v| v.abs()).sum::<f64>()).fold(0.0_f64, f64::max).sqrt()
+}
